def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    # Extract 4-connected nonzero objects.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            objects.append({'color': color, 'cells': cells})

    # Objects with enclosed background cells rise; solid objects fall.
    for obj in objects:
        cells = obj['cells']
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        occupied = set(cells)
        exterior = set()
        todo = []
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                if (r,c) not in occupied and (r in (r0,r1) or c in (c0,c1)):
                    exterior.add((r,c)); todo.append((r,c))
        while todo:
            r,c = todo.pop()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if r0 <= nr <= r1 and c0 <= nc <= c1 and (nr,nc) not in occupied and (nr,nc) not in exterior:
                    exterior.add((nr,nc)); todo.append((nr,nc))
        obj['up'] = any((r,c) not in occupied and (r,c) not in exterior
                        for r in range(r0,r1+1) for c in range(c0,c1+1))

    result = [[0]*w for _ in range(h)]
    settled = []
    # Compact hollow objects against the top, keeping their original order.
    for obj in sorted((o for o in objects if o['up']), key=lambda o: min(r for r,c in o['cells'])):
        cells = obj['cells']
        shift = 0
        while True:
            candidate = [(r+shift-1,c) for r,c in cells]
            if any(r < 0 for r,c in candidate) or any((r,c) in settled for r,c in candidate):
                break
            shift -= 1
        moved = [(r+shift,c) for r,c in cells]
        settled.extend(moved)
        obj['moved'] = moved

    # Compact solid objects against the bottom, keeping their original order.
    for obj in sorted((o for o in objects if not o['up']), key=lambda o: max(r for r,c in o['cells']), reverse=True):
        cells = obj['cells']
        shift = 0
        while True:
            candidate = [(r+shift+1,c) for r,c in cells]
            if any(r >= h for r,c in candidate) or any((r,c) in settled for r,c in candidate):
                break
            shift += 1
        moved = [(r+shift,c) for r,c in cells]
        settled.extend(moved)
        obj['moved'] = moved

    for obj in objects:
        for r,c in obj['moved']:
            result[r][c] = obj['color']
    return result

